<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Mini Spreadsheet</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }
    body {
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background-color: #f8fafc;
      color: #1e293b;
      padding: 24px;
      display: flex;
      flex-direction: column;
      align-items: center;
    }
    .app-container {
      width: 100%;
      max-width: 850px;
      min-width: 650px;
      min-height: 480px;
      background: #ffffff;
      border: 1px solid #e2e8f0;
      border-radius: 8px;
      box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
      padding: 20px;
    }
    header {
      margin-bottom: 16px;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    h1 {
      font-size: 18px;
      font-weight: 600;
      color: #0f172a;
    }
    .grid-wrapper {
      overflow-x: auto;
      border: 1px solid #cbd5e1;
      border-radius: 4px;
    }
    table {
      border-collapse: collapse;
      width: 100%;
      table-layout: fixed;
    }
    th, td {
      border: 1px solid #cbd5e1;
      height: 28px;
      padding: 0;
      text-align: center;
      font-size: 13px;
    }
    th {
      background-color: #f1f5f9;
      color: #475569;
      font-weight: 600;
      user-select: none;
    }
    th.col-header {
      width: calc((100% - 40px) / 10);
    }
    th.row-header {
      width: 40px;
    }
    td input {
      width: 100%;
      height: 100%;
      border: none;
      outline: none;
      padding: 0 6px;
      font-size: 13px;
      font-family: inherit;
      background: transparent;
      color: #0f172a;
    }
    td input:focus {
      background-color: #ffffff;
      box-shadow: inset 0 0 0 2px #2563eb;
    }
    .controls {
      margin-top: 20px;
      display: flex;
      flex-direction: column;
      gap: 10px;
    }
    button#export {
      align-self: flex-start;
      padding: 8px 16px;
